// AssetDetail defines model for AssetDetail.
type AssetDetail struct {
	// AddableSections The sections this kind can still be given, in catalog order. Present only while the owner is reading their own asset.
	AddableSections *[]AddableSection `json:"addableSections,omitempty"`

	// Blocks The asset's blocks in page order.
	Blocks []AssetBlock `json:"blocks"`

	// Blurb The catalog blurb the creator wrote for a person. Never the file's own description, which is a prompt written for a model.
	Blurb     string               `json:"blurb"`
	CreatedAt time.Time            `json:"createdAt"`
	Creator   string               `json:"creator"`
	Discovery AssetDetailDiscovery `json:"discovery"`

	// Downloads The formats this asset is offered in, read from its projection. A format Illarin cannot produce for the asset is absent rather than listed as unavailable, so this is a list of choices and not a capability report.
	Downloads []DownloadTarget   `json:"downloads"`
	Id        openapi_types.UUID `json:"id"`

	// IsNsfw Null while a draft has not been asked the adult content question. Nothing answers it on the creator's behalf.
	IsNsfw *bool `json:"isNsfw"`

	// IsOwner Whether the reader owns the asset. The owner's page is the reader's page with its editing affordances, not a second visual state.
	IsOwner bool            `json:"isOwner"`
	Kind    AssetDetailKind `json:"kind"`

	// Lifecycle A draft resolves for its owner alone. Discovery applies to a published asset only.
	Lifecycle AssetDetailLifecycle `json:"lifecycle"`

	// Media The asset's images, cover first. Variant URLs already reflect the reader's preference, so a blurred reader is never handed a clear one.
	Media []AssetImage `json:"media"`
	Name  string       `json:"name"`

	// Original The creator's own upload. Null for an asset built from nothing, which gets no group saying so.
	Original *OriginalUpload `json:"original"`

	// Preview The composed social preview for link unfurling. Null on a draft, which nothing unfurls.
	Preview *string `json:"preview"`

	// Readiness What publication is waiting on. Present only while the owner is reading their own draft.
	Readiness  *[]ReadinessItem      `json:"readiness,omitempty"`
	Tags       []AssetTag            `json:"tags"`
	Visibility AssetDetailVisibility `json:"visibility"`
	Withhold   *AssetWithhold        `json:"withhold,omitempty"`
}

